import React from "react";

/**
 * IconTrail
 * -----------
 * A continuous left-to-right icon trail that arches above whatever
 * content it's placed near (e.g. a logo/heading). Icons fade in as
 * they enter, fade out as they exit, and loop seamlessly.
 *
 * Usage:
 *   <div style={{ position: "relative" }}>
 *     <IconTrail />
 *     <img src={logo} ... />
 *     <h1>...</h1>
 *   </div>
 *
 * The parent element must have position: relative (or similar) so
 * this component's position: absolute anchors correctly above it.
 * Respects prefers-reduced-motion automatically.
 */

const spiral_swirl = "data:image/png;base64,";
const butterfly = "data:image/png;base64,";
const bunny = "data:image/png;base64,";
const sun_swirl = "data:image/png;base64,";
const radio_music = "data:image/png;base64,";
const bow = "data:image/png;base64,";
const clover = "data:image/png;base64,";
const clapperboard = "data:image/png;base64,";

const ICONS = [spiral_swirl, butterfly, bunny, sun_swirl, radio_music, bow, clover, clapperboard];

export default function IconTrail() {
  return (
    <div className="icon-trail-arch" aria-hidden="true">
      <style>{`
        .icon-trail-arch {
          position: absolute;
          top: -60px;
          left: 50%;
          width: 640px;
          max-width: 90vw;
          height: 150px;
          transform: translateX(-50%);
          z-index: 2;
          pointer-events: none;
          overflow: visible;

          -webkit-mask-image: linear-gradient(
            to right,
            transparent 0%,
            black 14%,
            black 86%,
            transparent 100%
          );
          mask-image: linear-gradient(
            to right,
            transparent 0%,
            black 14%,
            black 86%,
            transparent 100%
          );
        }

        .icon-trail-item {
          position: absolute;
          top: 0;
          left: 0;
          width: 30px;
          height: 30px;
          margin: -15px 0 0 -15px;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          opacity: 0;

          offset-path: path("M 0,150 Q 320,-30 640,150");
          offset-distance: 0%;
          offset-rotate: 0deg;

          animation: icon-trail-move 26s linear infinite;
        }

        @keyframes icon-trail-move {
          0%   { offset-distance: 0%;   opacity: 0; }
          8%   { opacity: 0.9; }
          50%  { opacity: 0.9; }
          92%  { opacity: 0.9; }
          100% { offset-distance: 100%; opacity: 0; }
        }

        @media (prefers-reduced-motion: reduce) {
          .icon-trail-item {
            animation: none;
            offset-distance: 50%;
            opacity: 0.9;
          }
        }

        @media (max-width: 640px) {
          .icon-trail-arch {
            top: -40px;
            width: 320px;
            height: 90px;
          }
          .icon-trail-item {
            width: 22px;
            height: 22px;
            margin: -11px 0 0 -11px;
            offset-path: path("M 0,90 Q 160,-18 320,90");
            animation-duration: 20s;
          }
        }
      `}</style>

      {ICONS.map((icon, i) => (
        <div
          key={i}
          className="icon-trail-item"
          style={{
            backgroundImage: `url(${icon})`,
            animationDelay: `${-((26 / ICONS.length) * i)}s`,
          }}
        />
      ))}
    </div>
  );
}
